    "question": "Why Did Jesus Die?",
    "shortAnswer": "Jesus died to save humanity from sin. Scripture teaches that His death was a sacrifice for our sins, demonstrated God's love, satisfied the demands of justice, reconciled sinners to God, and opened the way to eternal life.",
    "longAnswer": "The Bible describes sin as the fundamental human problem. “All have sinned, and come short of the glory of God” (Romans 3:23). Sin leads to death (Romans 6:23). Humanity therefore needed salvation from both sin and its consequences. Isaiah 53 predicted that the Messiah would be wounded for our transgressions and that “the LORD hath laid on him the iniquity of us all.” Jesus Himself explained His mission: “The Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many” (Mark 10:45). At the Last Supper, Jesus connected His blood with the forgiveness of sins (Matthew 26:28). The cross also reveals God's love. Romans 5:8 says that God demonstrated His love toward us because Christ died for us while we were sinners. 1 Peter 2:24 says Christ “bare our sins in his own body on the tree.” The cross therefore cannot be reduced to an example of suffering. Scripture presents it as central to God's plan of redemption.",
