    "id": "answer-eternal-security",
    "question": "What Is Salvation?",
    "shortAnswer": "Biblical salvation is God's rescue of humanity from sin, its consequences, and ultimately death. Salvation includes forgiveness, justification, reconciliation with God, transformation of character, and ultimately eternal life in God's kingdom.",
    "longAnswer": "The name Jesus itself is connected with salvation. The angel told Joseph, “thou shalt call his name JESUS: for he shall save his people from their sins” (Matthew 1:21). This is important because biblical salvation is not merely rescue from unpleasant circumstances. The deepest human problem is sin. Romans 3:23 says all have sinned. Romans 6:23 says the wages of sin are death, but “the gift of God is eternal life through Jesus Christ our Lord.” Salvation therefore begins with forgiveness and reconciliation to God. Romans 5:1 says, “Therefore being justified by faith, we have peace with God through our Lord Jesus Christ.” But salvation also involves transformation. 2 Corinthians 5:17 says that anyone who is in Christ is “a new creature.” Finally, salvation has a future dimension. Jesus will return, the dead will be raised, and God's people will receive immortality (1 Corinthians 15:51-54; 1 Thessalonians 4:16-17). Thus Scripture speaks of salvation as something believers have received, something God is accomplishing in them, and something that will be fully realized at Christ's return.",
