    "id": "answer-what-happens-to-your-soul-when-you-die",
    "question": "What Happens to Your Soul When You Die?",
    "shortAnswer": "According to the biblical description of human nature, the soul does not leave the body as an immortal conscious person. At death, the person ceases to live and returns to the dust, awaiting the resurrection.",
    "longAnswer": "Genesis 2:7 says that Adam became a living soul when God formed him from dust and gave him the breath of life. When a person dies, the reverse occurs. Ecclesiastes 12:7 says the dust returns to the earth and the spirit returns to God who gave it. This “spirit” should not automatically be understood as a conscious personality living independently of the body. James 2:26 says, “the body without the spirit is dead,” emphasizing the life-giving principle. The dead are repeatedly described as sleeping. Jesus called Lazarus's death sleep (John 11:11-14), and Paul called deceased believers those who had fallen asleep (1 Thessalonians 4:13-17). At the resurrection, God restores life. 1 Corinthians 15 explains that the mortal body is raised and transformed into immortality. The Christian hope is therefore not escape from the body into an eternal spiritual existence. It is resurrection and restoration.",
