    "id": "answer-christ-descended-dead",
    "question": "What Is the Resurrection?",
    "shortAnswer": "The resurrection is God's act of bringing the dead back to life. Scripture teaches a resurrection of the righteous to eternal life and a resurrection of the wicked to judgment.",
    "longAnswer": "The resurrection is one of the central teachings of the Bible. Daniel 12:2 describes people who “sleep in the dust” awakening. Jesus said: “The hour is coming, in the which all that are in the graves shall hear his voice, and shall come forth” (John 5:28-29). Jesus' own resurrection is the foundation of Christian hope. Paul calls Christ “the firstfruits of them that slept” (1 Corinthians 15:20). Because Christ rose, believers have the assurance that death does not have the final word. 1 Corinthians 15 explains that the resurrected body will be transformed. What is sown in corruption is raised in incorruption. What is mortal becomes immortal (1 Corinthians 15:42-54). Paul connects the resurrection of believers specifically with Christ's second coming (1 Thessalonians 4:16-17). The Bible therefore does not present eternal life as escape from death through an inherently immortal soul. Eternal life is ultimately received through resurrection.",
