    "id": "answer-who-wrote-the-bible",
    "question": "Who Wrote the Bible?",
    "shortAnswer": "The Bible was written by many human authors over many generations, but Scripture identifies God as the ultimate source of its inspired message.",
    "longAnswer": "Peter explains: “Holy men of God spake as they were moved by the Holy Ghost” (2 Peter 1:21). The Bible therefore has both a divine and human dimension. Different books identify different human writers. Moses wrote portions of the Law (Deuteronomy 31:24). Isaiah identifies himself as the prophet who received his message (Isaiah 1:1). Jeremiah identifies himself at the beginning of his book (Jeremiah 1:1). Paul identifies himself in his letters, for example Romans 1:1. Peter identifies himself in 1 Peter 1:1. John identifies himself as the recipient and recorder of Revelation (Revelation 1:1-2). Yet Scripture does not present these men as independent inventors of religious ideas. Their message came under the direction of the Holy Spirit. The Bible does not claim that every sentence was mechanically dictated word-for-word. Instead, it describes prophets and apostles speaking and writing under divine inspiration. This allows us to recognize both the individuality of biblical writers and the divine authority of Scripture.",
