    "question": "Are We Living in the End Times?",
    "shortAnswer": "The New Testament describes the Christian era as “the last days,” while also describing events that will intensify before Christ's return. Scripture therefore calls believers to watchfulness rather than date-setting.",
    "longAnswer": "Peter applied Joel's prophecy to the time of the early church and said: “it shall come to pass in the last days” (Acts 2:17). Hebrews likewise says that God: “hath in these last days spoken unto us by his Son” (Hebrews 1:2). In this sense, the “last days” began with the coming of Christ. Yet Scripture also describes a future culmination of evil immediately before the second coming. Paul writes: “in the last days perilous times shall come” (2 Timothy 3:1). Jesus' teachings in Matthew 24 describe events leading toward His return. The phrase “last days” can refer broadly to the era inaugurated by Christ, while Scripture also describes a final period immediately preceding His return. Therefore, the question should not simply be, “Can we prove that today is the last generation?” The more important biblical question is whether we are spiritually prepared for Christ's return.",
    "topics": [
      "Second Coming",
      "Prophecy"
    ],
    "category": "Life and Relationships",
    "scriptures": [
      "Acts 2:16-17",
      "Hebrews 1:1-2",
      "2 Timothy 3:1-5",
      "James 5:3-8",
      "Matthew 24"
    ],
