function slugify(value) {
  return value
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function answerUrl(answer) {
  return `/answers/${slugify(answer.question)}/`;
}

function topicUrl(topic) {
  return `/topics/${slugify(topic)}/`;
}

